stylesheet:
/* Hoja de estilos dinámica generada por ThemeEngine de Escritorio */
QMainWindow, QWidget#root {
    background-color: #E8DEC3;
    color: #3B2F2F;
    font-family: 'Segoe UI Variable Display', 'Segoe UI', -apple-system, sans-serif;
    font-size: 11px;
}

/* Barra de herramientas compacta (28px) */
QToolBar#mainToolbar {
    background-color: #E2D7BB;
    color: #3B2F2F;
    border-bottom: 1px solid #D2C3A0;
    min-height: 28px;
    max-height: 28px;
    padding: 0 4px;
}
QToolBar#mainToolbar QToolButton {
    font-size: 10px;
    height: 22px;
    padding: 2px 6px;
    border-radius: 3px;
}
QToolBar#mainToolbar QToolButton:hover {
    background-color: #D9CEB0;
}

/* Binder / Navegador jerárquico */
QTreeView#binder {
    background-color: #E8DEC3;
    color: #3B2F2F;
    border: none;
    border-right: 1px solid #D6C8A8;
    font-size: 11px;
}
QTreeView#binder::item {
    height: 22px;
}
QTreeView#binder::item:selected {
    background-color: #D9CEB0;
    color: #231B1B;
    border-radius: 3px;
}

/* Cabecera del Editor (24px) */
QWidget#editorHeader {
    background-color: #ECE3CD;
    color: #5C4A3E;
    min-height: 24px;
    max-height: 24px;
    border-bottom: 1px solid #D6C8A8;
    font-size: 10px;
}

/* Editor RTF */
QTextEdit#editor {
    background-color: #F4ECD8;
    color: #3B2F2F;
    selection-background-color: #E4D5B7;
    border: none;
    font-family: 'Georgia', 'Segoe UI Variable Text', serif;
}

/* Pizarra de Corcho (Corkboard) */
QWidget#corkboard {
    background-color: #DFD3B5;
}
QWidget#corkboardCard {
    background-color: #F7F1E1;
    color: #3B2F2F;
    border: 1px solid #CCBE9E;
    border-radius: 4px;
}

/* Esquematizador (Outliner) */
QTableView#outliner {
    background-color: #F4ECD8;
    color: #3B2F2F;
    gridline-color: #DFD3B5;
    border: none;
}
QTableView#outliner::item:alternate {
    background-color: #ECE4CE;
}

/* Inspector Lateral */
QDockWidget#inspector {
    background-color: #E8DEC3;
    color: #3B2F2F;
    border-left: 1px solid #D6C8A8;
}
QWidget#inspectorCard {
    background-color: #F7F1E1;
    border: 1px solid #D6C8A8;
    border-radius: 4px;
}

/* Barra de estado */
QStatusBar#statusBar {
    background-color: #E2D7BB;
    color: #6E5D4F;
    border-top: 1px solid #D2C3A0;
    min-height: 22px;
    font-size: 10px;
}

/* Micro-etiquetas y badges */
QLabel.microBadge {
    font-size: 9px;
    font-weight: bold;
    padding: 1px 4px;
    border-radius: 5px;
    background-color: #DACFB2;
    color: #8C5333;
}
